import { useState } from "react";

type SmoothImageProps = {
  src: string;
  alt: string;
};

const SmoothImage = ({ src, alt }: SmoothImageProps) => {
  const [loaded, setLoaded] = useState(false);

  let lowResSrc = src;

  if (src.includes("-min")) {
    // Replace `-min` with `-lowres` for both jpg and png
    lowResSrc = src.replace("-min", "-lowres");
  } else {
    // If no -min, append -lowres before file extension
    lowResSrc = src.replace(/(\.jpg|\.png)$/i, "-lowres$1");
  }

  return (
    <div
      style={{
        position: "relative",
        width: "100%",
        overflow: "hidden",
      }}
    >
      {/* Blurred placeholder */}
      <img
        src={lowResSrc}
        alt=""
        aria-hidden="true"
        style={{
          width: "100%",
          height: "auto",
          filter: "blur(20px)",
          position: "absolute",
          top: 0,
          left: 0,
          zIndex: 1,
          transition: "opacity 0.4s ease",
          opacity: loaded ? 0 : 1,
        }}
      />
      {/* Full-resolution image */}
      <img
        src={src}
        alt={alt}
        loading="lazy"
        onLoad={() => setLoaded(true)}
        style={{
          width: "100%",
          height: "auto",
          position: "relative",
          zIndex: 2,
          transition: "opacity 0.6s ease",
          opacity: loaded ? 1 : 0,
        }}
      />
    </div>
  );
};

export default SmoothImage;
